const fs = require('fs');
function fileFns(path) {
  const src = fs.readFileSync(path, 'utf8');
  const lines = src.split('\n');
  const fns = [];
  let cur = null, depth = 0, body = [];
  const fnRe = /^\s*(?:function\s+(\w+)|var\s+(\w+)\s*=\s*function)/;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!cur && fnRe.test(line)) {
      cur = { name: (fnRe.exec(line)[1] || fnRe.exec(line)[2]), start: i + 1, body: [] };
